      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">DIFFERENT WORLDS, SAME HABITS</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The convergence that proves the pattern</text>\n                    <rect x=\"80\" y=\"180\" width=\"940\" height=\"220\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"230\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">WHAT IS DIFFERENT</text>\n                    <text x=\"550\" y=\"280\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Diet: pecorino vs sweet potato vs beans vs greens</text>\n                    <text x=\"550\" y=\"320\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Religion: Catholic, Adventist, Confucian, Orthodox</text>\n                    <text x=\"550\" y=\"360\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Climate: alpine, desert, tropical, Mediterranean</text>\n                    <rect x=\"80\" y=\"430\" width=\"940\" height=\"540\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"480\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">WHAT IS THE SAME: THE POWER 9</text>\n                    <text x=\"130\" y=\"535\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">1. Move Naturally</text>\n                    <text x=\"600\" y=\"535\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">6. Wine at 5</text>\n                    <text x=\"130\" y=\"585\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">2. Purpose</text>\n                    <text x=\"600\" y=\"585\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">7. Belong (faith)</text>\n                    <text x=\"130\" y=\"635\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">3. Downshift stress</text>\n                    <text x=\"600\" y=\"635\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">8. Loved Ones First</text>\n                    <text x=\"130\" y=\"685\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">4. 80% Rule</text>\n                    <text x=\"600\" y=\"685\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">9. Right Tribe</text>\n                    <text x=\"130\" y=\"735\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">5. Plant Slant</text>\n                    <text x=\"550\" y=\"820\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Five separate cultures converge on nine habits</text>\n                    <text x=\"550\" y=\"860\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">The habits, not the geography, drive longevity</text>\n                    <text x=\"550\" y=\"920\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">The Power 9 is your portable Blue Zone</text>\n                </svg>",
