      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The Albert Lea effect</text>\n                    <rect x=\"150\" y=\"200\" width=\"800\" height=\"220\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">CITY-WIDE INTERVENTION</text>\n                    <text x=\"550\" y=\"315\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Sidewalks, menus, recess, moai groups</text>\n                    <text x=\"550\" y=\"365\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Engineered to default to belonging</text>\n                    <rect x=\"150\" y=\"460\" width=\"800\" height=\"220\" rx=\"20\" fill=\"rgba(99,102,241,0.15)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"515\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">3-YEAR RESULTS</text>\n                    <text x=\"550\" y=\"565\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">+2.9 years life expectancy</text>\n                    <text x=\"550\" y=\"610\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">~40% lower city employee healthcare</text>\n                    <text x=\"550\" y=\"655\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Smoking down 30%+, satisfaction up</text>\n                    <rect x=\"200\" y=\"720\" width=\"700\" height=\"280\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"780\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">THE THESIS CONFIRMED</text>\n                    <text x=\"550\" y=\"830\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Environment >> willpower</text>\n                    <text x=\"550\" y=\"870\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Community layer = high-leverage intervention</text>\n                    <text x=\"550\" y=\"930\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Replicated in 70+ US cities since</text>\n                    <text x=\"550\" y=\"970\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Blue Zones can be engineered, not only inherited</text>\n                </svg>",
